import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import siteConfig from '../../../tdesign-site/site/site.config.mjs';

// One-off release evidence. Inputs are generated by export_inventory.dart and
// tool/audit_api_docs.dart --json. This does not certify semantic equivalence.
const root = fileURLToPath(new URL('../../../', import.meta.url));
const [oldFile, currentFile, apiFile, outputFile] = process.argv.slice(2);
if (!outputFile) throw Error('Usage: node check_migration.mjs OLD_EXPORTS CURRENT_EXPORTS CURRENT_API OUTPUT');
const read = file => readFileSync(file, 'utf8');
const old = JSON.parse(read(oldFile));
const current = JSON.parse(read(currentFile));
const api = JSON.parse(read(apiFile));
const guidePath = 'tdesign-site/site/docs/migration-0.2.7-to-1.0.md';
const guide = read(root + guidePath);
const ids = [...guide.matchAll(/<a id="([^"]+)"><\/a>/g)].map(m => m[1]);
if (new Set(ids).size !== ids.length) throw Error('Duplicate guide anchor');
for (const m of guide.matchAll(/\]\(#([^)]+)\)/g)) {
  if (!ids.includes(m[1])) throw Error('Missing guide anchor: ' + m[1]);
}
const componentEntries = [...guide.matchAll(/<a id="migration-component-([^"]+)"><\/a>\n- \*\*\[([^\]]+)\]\(([^)]+)\)\*\*：([^\n]+)\n\n  \*\*需要调整\*\*：([^\n]+)/g)].map(m => ({
  slug: m[1], title: m[2], apiUrl: m[3], entry: m[4], instructions: m[5],
  status: 'source-reviewed-navigation-and-instructions; not full old-member/runtime certification',
}));
const routes = new Set(siteConfig.docs.flatMap(group => group.children ?? []).map(page => page.path));
for (const entry of componentEntries) {
  if (!routes.has(new URL(entry.apiUrl).pathname)) throw Error('Unknown component route: ' + entry.apiUrl);
}
if (componentEntries.length !== 57) throw Error('Expected all 57 component entries');
const rows = [...guide.matchAll(/^\| `([^`]+)` \| (.*?) \| (.*?) \|$/gm)];
const names = rows.map(m => m[1]);
if (new Set(names).size !== names.length) throw Error('Duplicate legacy row');
const missing = Object.keys(old.declarations).filter(n => !names.includes(n));
const extra = names.filter(n => !old.declarations[n]);
if (missing.length || extra.length) throw Error(JSON.stringify({ missing, extra }));
const legacyEntries = rows.map(m => {
  const targets = [...new Set(m[2].match(/\bT[A-Z]\w*/g) ?? [])];
  for (const n of targets) {
    if (n !== 'TIcons' && !current.declarations[n]) throw Error('Unexported migration target: ' + n);
  }
  const anchor = m[3].match(/\[具体改法\]\(#([^)]+)\)/)?.[1];
  if (!anchor || !ids.includes(anchor)) throw Error('Missing component disposition: ' + m[1]);
  return { old: m[1], ...old.declarations[m[1]], target: m[2], instructions: m[3], anchor,
    status: targets.length ? 'public-target-and-component-disposition-checked' : 'old-type-removed; component-rewrite-direction-checked',
    memberAndBusinessMigration: 'not exhaustively runtime-verified',
  };
});
for (const m of guide.matchAll(/`([^`]+)`/g)) {
  for (const n of m[1].matchAll(/\b(T[A-Z]\w*)\.(\w+)/g)) {
    if (n[1].startsWith('TD') || n[1] === 'TIcons') continue;
    const declaration = api.declarations[n[1]];
    if (declaration && !declaration.members.includes(n[2]) &&
        !declaration.constructors.includes(n[2]) && !declaration.callables[n[2]]) {
      throw Error('Unknown qualified API: ' + n[0]);
    }
  }
}
const hash = content => createHash('sha256').update(content).digest('hex');
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const candidate = '7d3cb3e26d3a83f4a1154061504d062fe7ac488e';
if (git('diff', candidate, '--', 'tdesign-component/lib', 'tdesign-component/example/assets/api')) {
  throw Error('Runtime/API docs differ from the reviewed release candidate');
}
const oldBaseline = JSON.parse(read(root + 'specs/058-release-preparation/public-api-diff.json'));
const enumChanges = oldBaseline.items.filter(row => row.before.kind === 'enum').flatMap(row => {
  const entry = legacyEntries.find(e => e.old === row.old);
  const target = entry.target.match(/\bT[A-Z]\w*/)?.[0];
  const oldValues = Object.keys(row.before.members).filter(k => k.startsWith('value:')).map(k => k.slice(6));
  const newValues = target && current.declarations[target]?.kind === 'EnumDeclaration' ? api.declarations[target].members : [];
  const removedNames = oldValues.filter(n => !newValues.includes(n));
  return removedNames.length ? [{old:row.old,target:entry.target,oldValues,currentValues:newValues,removedNames,disposition:entry.anchor,scope:'Value-name drift only; use guide for semantic mapping, never automatic substitution'}] : [];
});
const report = {
  baseline: { oldVersion: '0.2.7', oldTag: git('rev-parse', '0.2.7'), candidate,
    checkoutAtAudit: git('rev-parse', 'HEAD'), currentApiIssues: api.issues.length },
  scope: 'Own exports, navigation and source-reviewed instructions only; excludes inherited members, external re-exports and exhaustive business migration/visual certification.',
  exportNotes: { oldLocalShadows: old.localDeclarationsShadowingExports, oldCollisions: old.exportCollisionsRequiringResolution, currentLocalShadows: current.localDeclarationsShadowingExports, currentCollisions: current.exportCollisionsRequiringResolution },
  counts: { oldOwnExports: names.length, currentOwnExports: Object.keys(current.declarations).length,
    components: componentEntries.length, missingLegacyRows: missing.length, extraLegacyRows: extra.length },
  fingerprints: { guide: hash(guide), fixture: hash(read(root + 'tdesign-component/tool/fixtures/token_migration/lib/migration_027_to_100_examples.dart')),
    oldFiles: old.files, currentFiles: current.files },
  componentEntries, enumChanges, legacyEntries,
};
if (api.issues.length) throw Error('Current API audit has issues');
writeFileSync(outputFile, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report.counts));
